{'type': 'text', 'text': '{
  "id": "score",
  "type": "llm_transform",
  "name": "Score stance per row",
  "inputs": [
    {
      "id": "load",
      "schema": {
        "columns": [
          {
            "name": "doc_id",
            "type": "str",
            "nullable": false
          },
          {
            "name": "body",
            "type": "str",
            "nullable": false
          }
        ],
        "primary_key": [
          "doc_id"
        ]
      }
    }
  ],
  "output_schema": {
    "columns": [
      {
        "name": "doc_id",
        "type": "str",
        "nullable": false
      },
      {
        "name": "body",
        "type": "str",
        "nullable": false
      },
      {
        "name": "stance",
        "type": "str",
        "nullable": false
      }
    ],
    "primary_key": [
      "doc_id"
    ]
  },
  "llm": {
    "prompt_template": "Classify the stance in {row}. Output the stance word twice, separated by a space (e.g. \"for for\" or \"against against\").",
    "model": "claude-sonnet-4-6",
    "temperature": 0.0,
    "max_retries": 3,
    "response_format": "json"
  },
  "compiler_notes": []
}'}

{'type': 'text', 'text': '{
  "id": "double_stance",
  "type": "python_row_function",
  "name": "Double stance",
  "inputs": [
    {
      "id": "score"
    }
  ],
  "output_schema": {
    "columns": [
      {
        "name": "doc_id",
        "type": "str",
        "nullable": false
      },
      {
        "name": "body",
        "type": "str",
        "nullable": false
      },
      {
        "name": "stance",
        "type": "str",
        "nullable": false
      }
    ],
    "primary_key": [
      "doc_id"
    ]
  },
  "function": {
    "kind": "inline",
    "code": "row['stance'] = row['stance'] + ' ' + row['stance']\nreturn row",
    "requirements": []
  },
  "compiler_notes": []
}'}

